from __future__ import annotations

import fnmatch
import os
import subprocess
from datetime import datetime
from pathlib import Path

from rich.console import Console
from rich.panel import Panel
from rich.table import Table


class CodeScout:
    """Orchestrator that delegates to internal scanners and formats output via rich."""

    _SKIP_DIRS = {".git", "node_modules", "__pycache__"}
    _TAGS = {"TODO", "FIXME", "HACK", "XXX"}
    _COMMENT_PREFIXES = ("#", "//", "/*")

    def __init__(
        self,
        path: Path,
        console: Console,
        ignore_patterns: list[str] | None = None,
    ) -> None:
        """Initialize with target directory and rich console instance.

        Raises ValueError if *path* does not exist or is not a directory.
        """
        self.path = Path(path)
        if not self.path.exists():
            raise ValueError(f"Path does not exist: {self.path}")
        if not self.path.is_dir():
            raise ValueError(f"Path is not a directory: {self.path}")
        self.console = console
        self._ignore_patterns = ignore_patterns or []

    # ------------------------------------------------------------------ helpers

    def _walk(self) -> list[Path]:
        """Yield all file paths under self.path, skipping well-known dirs and ignored patterns."""
        result: list[Path] = []
        for dirpath, dirnames, filenames in os.walk(self.path, onerror=lambda e: None):
            # prune directories in-place
            dirnames[:] = [d for d in dirnames if d not in self._SKIP_DIRS]
            # prune ignored directories
            if self._ignore_patterns:
                dirnames[:] = [
                    d
                    for d in dirnames
                    if not self._matches_ignore(str(Path(dirpath, d).relative_to(self.path)))
                ]
            for fn in filenames:
                fpath = Path(dirpath) / fn
                rel = str(fpath.relative_to(self.path))
                if self._ignore_patterns and self._matches_ignore(rel):
                    continue
                result.append(fpath)
        return result

    def _matches_ignore(self, rel_path: str) -> bool:
        """Return True if *rel_path* matches any of the user-supplied ignore patterns."""
        for pat in self._ignore_patterns:
            if fnmatch.fnmatch(rel_path, pat):
                return True
        return False

    def _is_comment_line(self, line: str) -> bool:
        """Return True if *line* looks like a comment (starts with one of the prefixes)."""
        stripped = line.lstrip()
        return any(stripped.startswith(p) for p in self._COMMENT_PREFIXES)

    def _format_size(self, size_bytes: int) -> str:
        """Return a human-readable size string (KB)."""
        return f"{size_bytes / 1024:.1f}"

    # ------------------------------------------------------------------ todos

    def scan_todos(self, tag: str | None = None, context_lines: int = 1) -> None:
        """Walk the tree and print rich panels for TODO/FIXME/HACK/XXX comment matches."""
        try:
            files = self._walk()
        except PermissionError as exc:
            self.console.print(Panel(f"Permission denied scanning {self.path}: {exc}", style="red"))
            return
        target_tags = {tag.upper()} if tag else self._TAGS
        matches: list[tuple[Path, int, str]] = []

        for fpath in self._walk():
            try:
                text = fpath.read_text(encoding="utf-8")
            except (UnicodeDecodeError, PermissionError):
                continue

            lines = text.splitlines()
            for i, line in enumerate(lines):
                if not self._is_comment_line(line):
                    continue
                upper = line.upper()
                for t in target_tags:
                    if t in upper:
                        matches.append((fpath, i + 1, line))
                        break

        if not matches:
            self.console.print(Panel("No TODO/FIXME/HACK/XXX matches found.", style="yellow"))
            return

        for fpath, lineno, matched_line in matches:
            lines = fpath.read_text(encoding="utf-8").splitlines()
            start = max(0, lineno - 1 - context_lines)
            end = min(len(lines), lineno + context_lines)

            body_parts: list[str] = []
            for j in range(start, end):
                prefix = ">>> " if j == lineno - 1 else "    "
                body_parts.append(f"{prefix}{lines[j]}")

            header = f"[bold]{fpath}:[{lineno}]"
            self.console.print(Panel("\n".join(body_parts), title=header, border_style="red bold"))

    # ------------------------------------------------------------------ recent

    def scan_recent(self, days: int = 7) -> None:
        """Print a rich table of files modified in the last N days via git log."""
        try:
            result = subprocess.run(
                ["git", "log", f"--since={days}days", "--name-only",
                 "--pretty=format:"],
                capture_output=True, text=True, cwd=self.path,
            )
        except FileNotFoundError:
            self.console.print(Panel("git not found — cannot scan recent files.", style="red"))
            return
        except PermissionError as exc:
            self.console.print(Panel(f"Permission denied accessing {self.path}: {exc}", style="red"))
            return

        if result.returncode != 0:
            self.console.print(Panel("Not a git repository — cannot scan recent files.", style="yellow"))
            return

        seen: dict[str, float] = {}
        for raw_path in result.stdout.strip().splitlines():
            p = raw_path.strip()
            if not p:
                continue
            full = self.path / p
            try:
                mtime = os.path.getmtime(full)
            except OSError:
                continue
            if p not in seen or mtime > seen[p]:
                seen[p] = mtime

        if not seen:
            self.console.print(Panel(f"No files modified in the last {days} days.", style="yellow"))
            return

        sorted_files = sorted(seen.items(), key=lambda kv: kv[1], reverse=True)

        table = Table(title=f"Files modified in the last {days} days")
        table.add_column("File", style="cyan")
        table.add_column("Size (KB)", justify="right")
        table.add_column("Last Modified", style="green")

        for rel, mtime in sorted_files:
            full = self.path / rel
            try:
                size_kb = self._format_size(os.path.getsize(full))
            except OSError:
                size_kb = "—"
            date_str = datetime.fromtimestamp(mtime).strftime("%Y-%m-%d %H:%M")
            table.add_row(rel, size_kb, date_str)

        self.console.print(table)

    # ------------------------------------------------------------------ large

    def scan_large(self, min_size: int = 50_000) -> None:
        """Print a rich table of files at or above the given byte threshold."""
        try:
            entries: list[tuple[Path, int]] = []

            for fpath in self._walk():
                try:
                    size = os.path.getsize(fpath)
                except OSError:
                    continue
                if size >= min_size:
                    entries.append((fpath, size))
        except PermissionError as exc:
            self.console.print(Panel(f"Permission denied scanning {self.path}: {exc}", style="red"))
            return

        if not entries:
            self.console.print(Panel(f"No files >= {min_size} bytes found.", style="yellow"))
            return

        entries.sort(key=lambda kv: kv[1], reverse=True)

        table = Table(title=f"Files >= {min_size} bytes")
        table.add_column("File", style="cyan")
        table.add_column("Size (KB)", justify="right")

        for fpath, size in entries:
            rel = str(fpath.relative_to(self.path))
            table.add_row(rel, self._format_size(size))

        self.console.print(table)

from __future__ import annotations

import subprocess
from dataclasses import dataclass
from datetime import datetime, timezone
from pathlib import Path


@dataclass(frozen=True)
class RecentFile:
    """A file touched in a recent git commit."""

    path: str
    last_modified: datetime
    commit_hash: str
    commit_message: str


def is_git_repo(path: Path) -> bool:
    """Return True if the given path is inside a git work tree."""
    try:
        result = subprocess.run(
            ["git", "rev-parse", "--is-inside-work-tree"],
            cwd=path,
            capture_output=True,
            text=True,
        )
        return result.stdout.strip() == "true"
    except (subprocess.SubprocessError, FileNotFoundError):
        return False


def scan_recent_files(repo_path: Path, days: int = 7) -> list[RecentFile]:
    """Return deduplicated RecentFile objects for files touched in the last N days, sorted newest-first."""
    if not is_git_repo(repo_path):
        return []

    since_arg = f"{days} days ago"
    try:
        proc = subprocess.Popen(
            [
                "git",
                "log",
                f"--since={since_arg}",
                "--name-only",
                "--format=%H%n%s%n%aI",
            ],
            cwd=repo_path,
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
            text=True,
        )
    except (subprocess.SubprocessError, FileNotFoundError):
        return []

    seen: dict[str, RecentFile] = {}
    current_hash: str | None = None
    current_message: str | None = None
    current_date: datetime | None = None
    state = "hash"  # hash -> message -> date -> blank -> files -> (blank resets to hash)

    for line in proc.stdout:
        stripped = line.rstrip("\n")

        if not stripped:
            # Blank line: after date we enter files; between commits we reset
            if state == "date":
                state = "files"
            elif state == "files":
                # Blank line between commits — reset for next commit
                current_hash = None
                current_message = None
                current_date = None
                state = "hash"
            continue

        if state == "hash":
            current_hash = stripped
            state = "message"
        elif state == "message":
            current_message = stripped
            state = "date"
        elif state == "date":
            try:
                current_date = datetime.fromisoformat(stripped)
            except ValueError:
                current_date = datetime.now(timezone.utc)
        elif state == "files":
            filepath = stripped.lstrip("./")
            if current_hash and current_message:
                if filepath not in seen:
                    seen[filepath] = RecentFile(
                        path=filepath,
                        last_modified=current_date or datetime.now(timezone.utc),
                        commit_hash=current_hash,
                        commit_message=current_message,
                    )

    proc.wait()
    return list(seen.values())

"""Scan a directory tree for files exceeding a minimum size threshold."""

from __future__ import annotations

import fnmatch
import os
import sys
from pathlib import Path

DEFAULT_IGNORE_PATTERNS = [
    "node_modules/**",
    "__pycache__/**",
    ".git/**",
]


def _matches_ignore(rel_path: str, patterns: list[str]) -> bool:
    """Return True if *rel_path* matches any of the given fnmatch patterns."""
    for pat in patterns:
        if fnmatch.fnmatch(rel_path, pat):
            return True
    return False


def scan_large_files(
    root: str,
    min_size_bytes: int = 1_048_576,
    ignore_patterns: list[str] | None = None,
) -> list[dict]:
    """Walk *root* and return files >= *min_size_bytes*, sorted descending by size.

    Each dict has keys ``"path"`` (absolute), ``"size_bytes"``, and
    ``"relative_path"`` (relative to *root*).  Symlinks are skipped.
    Permission errors are logged to stderr and the offending entry is
    silently skipped.  A non-existent *root* raises ``FileNotFoundError``.
    """
    root_path = Path(root).resolve()
    if not root_path.exists():
        raise FileNotFoundError(f"Root directory does not exist: {root}")

    patterns = ignore_patterns if ignore_patterns is not None else DEFAULT_IGNORE_PATTERNS
    results: list[dict] = []

    for dirpath, dirnames, filenames in os.walk(root_path, followlinks=False):
        # Prune ignored directories in-place so os.walk won't descend.
        dirnames[:] = [
            d
            for d in dirnames
            if not _matches_ignore(
                str(Path(dirpath, d).relative_to(root_path)), patterns
            )
        ]

        for fname in filenames:
            full = Path(dirpath) / fname
            rel = str(full.relative_to(root_path))

            # Skip symlinks (including broken ones).
            if full.is_symlink():
                continue

            # Skip ignored files.
            if _matches_ignore(rel, patterns):
                continue

            try:
                size = os.path.getsize(full)
            except OSError as exc:
                print(f"Warning: cannot stat {full}: {exc}", file=sys.stderr)
                continue

            if min_size_bytes <= 0 or size >= min_size_bytes:
                results.append(
                    {
                        "path": str(full),
                        "size_bytes": size,
                        "relative_path": rel,
                    }
                )

    results.sort(key=lambda r: r["size_bytes"], reverse=True)
    return results


def _human_size(nbytes: int) -> str:
    """Return a human-readable size string (KB / MB / GB)."""
    if nbytes < 1024:
        return f"{nbytes} B"
    if nbytes < 1024**2:
        return f"{nbytes / 1024:.1f} KB"
    if nbytes < 1024**3:
        return f"{nbytes / 1024**2:.1f} MB"
    return f"{nbytes / 1024**3:.1f} GB"


def format_results(results: list[dict]) -> str:
    """Return a human-readable table string of *results* with sizes in KB/MB/GB."""
    if not results:
        return ""

    # Compute column widths.
    path_w = max(len(r["relative_path"]) for r in results)
    size_w = 10

    header = f"{'Path':<{path_w}}   {'Size':>{size_w}}"
    sep = "-" * len(header)
    lines = [header, sep]

    for r in results:
        lines.append(
            f"{r['relative_path']:<{path_w}}   {_human_size(r['size_bytes']):>{size_w}}"
        )

    return "\n".join(lines)

